//! Program icons: Superlogical's Rex icon set (`resources/program-icons`, generated by
//! `scripts/program-icons.py`) and which one a running program gets.
//!
//! Each icon is a full-colour tile, and its glyph alone, drawn as a one-colour silhouette
//! (`El::icon_one_color`) in the chrome's ink, as the official client draws its template
//! glyphs; colour tab icons draw that silhouette in the icon's tint.

mod catalog;

use std::{collections::HashMap, sync::LazyLock};

use rune::Icon;

pub struct ProgramIcon {
    /// The program's name, as the icon set writes it ("Claude Code", "Neovim").
    #[cfg_attr(not(test), allow(dead_code))]
    pub name: &'static str,
    pub slug: &'static str,
    /// The glyph's colour on dark chrome: the icon's own hue, at least 3:1 on every palette's
    /// tab and popover surfaces.
    pub tint: u32,
    /// The glyph on a square, its own colours standing for coverage only.
    pub glyph: Icon,
    /// The tile with its glyph, on a square centred on the tile.
    pub tile: Icon,
}

